def add_code_block(doc, text, font_size=9):
    """Добавляет текст в стиле кода (моноширинный шрифт, рамка)"""
    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(4)
    p.paragraph_format.space_after = Pt(4)
    p.paragraph_format.left_indent = Cm(1)
    p.paragraph_format.right_indent = Cm(0.5)

    # Фон (через shading)
    shading_elm = p._element.get_or_add_pPr()
    shading = OxmlElement('w:shd')
    shading.set(qn('w:fill'), 'F5F5F5')
    shading_elm.append(shading)

    run = p.add_run(text)
    run.font.name = 'Courier New'
    run.font.size = Pt(font_size)
    run.font.color.rgb = RGBColor(33, 33, 33)
    return p


def create_lab3_report():
    doc = Document()

    # Настройка стилей
    style = doc.styles['Normal']
    font = style.font
    font.name = 'Times New Roman'
    font.size = Pt(14)

    # Для абзацев с моноширинным шрифтом
